mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("edges=0-1:1,0-2:4,1-2:2,1-3:5,2-3:3","1,2,3"),
        ("edges=0-1:2,1-2:3,0-2:10","2,3"),
        ("edges=0-1:1,1-2:1,0-2:5","1,1"),
        ("edges=0-1:7","7"),
        ("edges=0-1:3,0-2:2,1-2:1,2-3:4","1,2,4"),
        ("  \nedges=0-1:1,0-2:4,1-2:2,1-3:5,2-3:3\n  ","1,2,3"),
        ("\nedges=0-1:3,0-2:2,1-2:1,2-3:4\n","1,2,4")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS kruskal-mst");
}
